        { hanzi: "碗", pinyin: "wǎn", meaning: "cl. bols", meaningEn: "cl. bowls" },
        { hanzi: "只", pinyin: "zhī", meaning: "cl. animaux", meaningEn: "cl. animals" },
        { hanzi: "辆", pinyin: "liàng", meaning: "cl. véhicules", meaningEn: "cl. vehicles" },
        { hanzi: "双", pinyin: "shuāng", meaning: "cl. paires", meaningEn: "cl. pairs" }
