        { zh: [{ text: "她", pinyin: "tā", role: "sujet" }, { text: "买", pinyin: "mǎi", role: "verbe" }, { text: "了", pinyin: "le", role: "particule" }, { text: "两本书", pinyin: "liǎng běn shū", role: "objet" }], fr: [{ text: "Elle a", role: "sujet" }, { text: "acheté", role: "verbe" }, { text: "deux livres", role: "objet" }], en: [], note: "Quantité (两本) sert de complément suffisant — le 了 perfectif a besoin d'un nombre ou objet pour respirer.", noteEn: "" },
        { zh: [{ text: "我", pinyin: "wǒ", role: "sujet" }, { text: "没", pinyin: "méi", role: "modificateur" }, { text: "吃", pinyin: "chī", role: "verbe" }, { text: "饭", pinyin: "fàn", role: "objet" }], fr: [{ text: "Je n'ai", role: "sujet" }, { text: "pas", role: "modificateur" }, { text: "mangé", role: "verbe" }], en: [], note: "NÉGATION : 没 (Modificateur) + V — JAMAIS de 了 dans la négation. ✗ 我没吃了 = faux.", noteEn: "" }
