        { hanzi: "迟到", pinyin: "chídào", meaning: "arriver en retard", meaningEn: "be late" },
        { hanzi: "下雨", pinyin: "xiàyǔ", meaning: "pleuvoir", meaningEn: "rain" },
        { hanzi: "重复", pinyin: "chóngfù", meaning: "répéter", meaningEn: "repeat" },
        { hanzi: "一遍", pinyin: "yībiàn", meaning: "une fois (entière)", meaningEn: "once (through)" }
