        { zh: [{ text: "他", pinyin: "tā", role: "sujet" }, { text: "正在", pinyin: "zhèng zài", role: "modificateur" }, { text: "睡觉", pinyin: "shuì jiào", role: "verbe" }], fr: [{ text: "Il est justement en train de", role: "modificateur" }, { text: "dormir", role: "verbe" }], en: [], note: "PROGRESSIF FORT : 正在 insiste sur l'instant précis (« n'interromps pas »).", noteEn: "" },
        { zh: [{ text: "他", pinyin: "tā", role: "sujet" }, { text: "坐", pinyin: "zuò", role: "verbe" }, { text: "着", pinyin: "zhe", role: "particule" }], fr: [{ text: "Il est", role: "sujet" }, { text: "assis", role: "verbe" }], en: [], note: "STATIQUE : 着 APRÈS le verbe = état figé. La photo, pas la vidéo.", noteEn: "" },
        { zh: [{ text: "门", pinyin: "mén", role: "sujet" }, { text: "开", pinyin: "kāi", role: "verbe" }, { text: "着", pinyin: "zhe", role: "particule" }], fr: [{ text: "La porte", role: "sujet" }, { text: "est ouverte", role: "verbe" }], en: [], note: "État résultat : la porte EST DANS l'état « ouverte » (pas en train de s'ouvrir).", noteEn: "" }
