        { hanzi: "后来", pinyin: "hòulái", meaning: "plus tard", meaningEn: "later on" },
        { hanzi: "最后", pinyin: "zuìhòu", meaning: "finalement", meaningEn: "finally" },
        { hanzi: "突然", pinyin: "tūrán", meaning: "soudain", meaningEn: "suddenly" },
        { hanzi: "当时", pinyin: "dāngshí", meaning: "à ce moment", meaningEn: "at that moment" }
