        { hanzi: "回忆", pinyin: "huíyì", meaning: "souvenir, mémoire", meaningEn: "memory" },
        { hanzi: "转眼", pinyin: "zhuǎnyǎn", meaning: "en un clin d'œil", meaningEn: "in a blink" }
