        { hanzi: "具体", pinyin: "jùtǐ", meaning: "concret, précis", meaningEn: "concrete, specific" },
        { hanzi: "评价", pinyin: "píngjià", meaning: "évaluation", meaningEn: "evaluation" },
        { hanzi: "认真", pinyin: "rènzhēn", meaning: "sérieux", meaningEn: "serious" }
