        { hanzi: "必然", pinyin: "bìrán", meaning: "nécessairement", meaningEn: "necessarily" },
        { hanzi: "难怪", pinyin: "nánguài", meaning: "pas étonnant", meaningEn: "no wonder" },
        { hanzi: "原来", pinyin: "yuánlái", meaning: "en fait, originellement", meaningEn: "actually, originally" },
        { hanzi: "犯错", pinyin: "fàncuò", meaning: "faire une erreur", meaningEn: "make a mistake" }
