        { hanzi: "反之", pinyin: "fǎnzhī", meaning: "à l'inverse", meaningEn: "conversely" },
        { hanzi: "然而", pinyin: "ránér", meaning: "cependant", meaningEn: "however" },
        { hanzi: "拒绝", pinyin: "jùjué", meaning: "refuser", meaningEn: "refuse" },
        { hanzi: "成本", pinyin: "chéngběn", meaning: "coût", meaningEn: "cost" }
