        { hanzi: "从而", pinyin: "cóngér", meaning: "et par là", meaningEn: "thereby" },
        { hanzi: "开支", pinyin: "kāizhī", meaning: "dépense", meaningEn: "expenditure" },
        { hanzi: "利润", pinyin: "lìrùn", meaning: "bénéfice", meaningEn: "profit" }
