        { hanzi: "志愿者", pinyin: "zhìyuànzhě", meaning: "bénévole", meaningEn: "volunteer" },
        { hanzi: "致力于", pinyin: "zhìlìyú", meaning: "se consacrer à", meaningEn: "be dedicated to" },
        { hanzi: "诚邀", pinyin: "chéngyāo", meaning: "inviter sincèrement", meaningEn: "sincerely invite" }
