        { hanzi: "金庸", pinyin: "jīnyōng", meaning: "Jin Yong", meaningEn: "Jin Yong" },
        { hanzi: "武侠", pinyin: "wǔxiá", meaning: "roman de chevalerie", meaningEn: "wuxia novel" }
