        { hanzi: "记忆", pinyin: "jìyì", meaning: "mémoire", meaningEn: "memory" },
        { hanzi: "反映", pinyin: "fǎnyìng", meaning: "refléter", meaningEn: "reflect" },
        { hanzi: "时代", pinyin: "shídài", meaning: "époque", meaningEn: "era" }
