        { hanzi: "冲突", pinyin: "chōngtū", meaning: "conflit, choc", meaningEn: "conflict" },
        { hanzi: "融合", pinyin: "rónghé", meaning: "fusion", meaningEn: "fusion" },
        { hanzi: "被视为", pinyin: "bèi shìwèi", meaning: "être vu comme", meaningEn: "be viewed as" },
        { hanzi: "跨文化", pinyin: "kuàwénhuà", meaning: "interculturel", meaningEn: "cross-cultural" }
